-- Snapshot of db/schema.sql before migration 001 (as applied to the first Neon
-- database). Used only by tests to check that the migration upgrades it to the
-- current schema. Do not edit.
-- Schema for lead capture and first-party funnel analytics.
-- Apply once in the Neon SQL Editor (or any Postgres 14+). It is idempotent:
-- running it again changes nothing and deletes nothing.

create table if not exists leads (
  id uuid primary key default gen_random_uuid(),

  -- Always stored trimmed and lower-cased by the application.
  email text not null
    check (email = lower(btrim(email)) and char_length(email) between 3 and 254),

  -- SHA-256 (hex) of the guide access token. The token itself is never stored.
  guide_token_hash text not null check (guide_token_hash ~ '^[0-9a-f]{64}$'),
  guide_token_expires_at timestamptz not null,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  -- Marketing consent is separate from the guide request and optional.
  marketing_consent boolean not null default false,
  marketing_consent_at timestamptz,
  marketing_consent_text_version text check (char_length(marketing_consent_text_version) <= 40),

  -- Version of the privacy notice shown when the guide was last requested.
  privacy_notice_version text not null check (char_length(privacy_notice_version) between 1 and 40),

  -- Acquisition context of the most recent guide request.
  variant text not null check (variant in ('compare', 'fees')),
  session_id uuid not null,
  utm_source text check (char_length(utm_source) <= 80),
  utm_medium text check (char_length(utm_medium) <= 80),
  utm_campaign text check (char_length(utm_campaign) <= 80),
  utm_content text check (char_length(utm_content) <= 80),
  utm_term text check (char_length(utm_term) <= 80),

  -- When a lead without marketing consent becomes due for deletion.
  -- Null while marketing consent is active: those rows are kept until the
  -- consent is withdrawn (see docs/operations.md).
  retention_expires_at timestamptz,

  constraint leads_consent_metadata_consistent check (
    (marketing_consent
      and marketing_consent_at is not null
      and marketing_consent_text_version is not null)
    or
    (not marketing_consent
      and marketing_consent_at is null
      and marketing_consent_text_version is null)
  ),
  constraint leads_retention_matches_consent check (
    (marketing_consent and retention_expires_at is null)
    or (not marketing_consent and retention_expires_at is not null)
  ),
  constraint leads_token_expires_after_update check (guide_token_expires_at > updated_at)
);

-- One lead per email address, ignoring case.
create unique index if not exists leads_email_lower_key on leads (lower(email));
create unique index if not exists leads_guide_token_hash_key on leads (guide_token_hash);
create index if not exists leads_retention_expires_at_idx on leads (retention_expires_at)
  where retention_expires_at is not null;

create table if not exists funnel_events (
  id uuid primary key default gen_random_uuid(),

  -- Generated by the sender; a repeated delivery of the same event is ignored.
  event_id uuid not null,
  session_id uuid not null,

  name text not null check (name in (
    'page_view', 'comparison_view', 'calculator_used', 'cta_click',
    'form_start', 'form_submit', 'form_error',
    'lead_created', 'guide_download'
  )),
  variant text not null check (variant in ('compare', 'fees')),

  -- Pathname only, from a fixed list. Never a query string.
  path text not null check (path in (
    '/', '/poplatky', '/dekujeme', '/ochrana-osobnich-udaju', '/api/guide'
  )),

  occurred_at timestamptz not null default now(),

  -- Small object of allow-listed keys (see docs/funnel.md).
  properties jsonb not null default '{}'::jsonb
    check (jsonb_typeof(properties) = 'object' and pg_column_size(properties) <= 512),

  utm_source text check (char_length(utm_source) <= 80),
  utm_medium text check (char_length(utm_medium) <= 80),
  utm_campaign text check (char_length(utm_campaign) <= 80),
  utm_content text check (char_length(utm_content) <= 80),
  utm_term text check (char_length(utm_term) <= 80)
);

create unique index if not exists funnel_events_event_id_key on funnel_events (event_id);
create index if not exists funnel_events_name_occurred_at_idx on funnel_events (name, occurred_at);
create index if not exists funnel_events_session_id_idx on funnel_events (session_id);
create index if not exists funnel_events_variant_campaign_idx on funnel_events (variant, utm_campaign);
